typedef struct Glyph { const char *name; int w, h; unsigned refs; } Glyph;

Glyph *glyph_intern(const char *name) {            /* FlyweightFactory */
    ENTRY key = { (char *)name, NULL }, *hit = hsearch(key, FIND);
    if (hit) { Glyph *g = hit->data; g->refs++; return g; }
    Glyph *g = glyph_new(name);                    /* intrinsic state only */
    ENTRY ins = { (char *)name, g };
    hsearch(ins, ENTER);
    return g;
}
